package com.jnapanam.sportszone.usermanagement.dto;import com.jnapanam.sportszone.identity.model.*;import java.util.*;public record AdminUserResponse(UUID id,String fullName,String email,String mobile,UserStatus status,Set<RoleName>roles,String addressLine,String city,String state,String postalCode,String emergencyContactName,String emergencyContactMobile,boolean forcePasswordChange,boolean requiresUpfrontPayment){public static AdminUserResponse from(User u){return new AdminUserResponse(u.getId(),u.getFullName(),u.getEmail(),u.getMobile(),u.getStatus(),u.getRoles().stream().map(Role::getName).collect(java.util.stream.Collectors.toUnmodifiableSet()),u.getAddressLine(),u.getCity(),u.getState(),u.getPostalCode(),u.getEmergencyContactName(),u.getEmergencyContactMobile(),u.isForcePasswordChange(),u.isRequiresUpfrontPayment());}}
